import type { TimelineRecord } from "../lib/bible-timeline";
import type { ChapterMapping, ContextTimelineRecord } from "./contextual-timeline";
import { buildAnchoredContext, type AnchoredEpisode } from "./contextual-timeline-anchors";

export const KINGS_TIMELINE_SOURCES = {
  regnalCounting: { title: "Encyclopedia of the Bible: Books of Kings, chronology", url: "https://www.biblegateway.com/resources/encyclopedia-of-the-bible/Books-Kings", use: "Comparison of accession/non-accession numbering, spring/fall calendars, and proposed changes of practice. These conventions are evaluated against KJV synchronisms; no textual emendation or universal offset is adopted." },
  omri: { title: "Encyclopedia of the Bible: Omri", url: "https://www.biblegateway.com/resources/encyclopedia-of-the-bible/Omri", use: "Calendar comparison for Omri's divided and sole rule and Ahab's c. 874/873 BC accession. KJV reign totals are retained." },
  jehu: { title: "Encyclopedia of the Bible: Jehu", url: "https://www.biblegateway.com/resources/encyclopedia-of-the-bible/Jehu", use: "Assyrian synchronisms and the proposed c. 853 BC Ahab / c. 841 BC Jehu transition dates. These are calendar reconstructions, not dates printed in Kings." },
  assyrianIsrael: { title: "UCL / Oracc: Israel, the House of Omri", url: "https://oracc.museum.upenn.edu/saao/aebp/Essentials/Countries/Israel/index.html", use: "Assyrian evidence for Jehu's tribute and the eighth-century interventions. Imperial claims do not override the biblical narrative or establish biological descent from Omri." },
  tiglath: { title: "UCL / Oracc: Tiglath-pileser III", url: "https://oracc.museum.upenn.edu/saao/aebp/Essentials/Kings/Tiglath-pileserIII/index.html", use: "Assyrian reign c. 744–727 BC (745 used for accession elsewhere), and the 732 BC Damascus/Israel campaign. Calendar setting for 2 Kings 15–16." },
};
const episodes: AnchoredEpisode[] = [];
function add(id: string, label: string, references: string[], note: string, at?: AnchoredEpisode["at"], until?: AnchoredEpisode["until"], kind?: TimelineRecord["kind"], sources?: string[]) {
  episodes.push({ id, label, references, note, at, until, kind, sources, era: "kingdom" });
}
const unknown = (id: string, label: string, references: string[], note: string, sources?: string[]) => add(id, label, references, note, undefined, undefined, undefined, sources);

// Accession/reign anchors are activity, never lifespan evidence for their kings.
add("royal-saul", "Saul · reign", ["ACT.13.21", "1SA.13.1", "1SA.31.6"], "Reuses the shared forty-year working reign before David. The KJV's one-year/two-year wording in 1 Samuel 13:1 is retained; it is not replaced with an invented accession age or a different reign total.", ["saul_618"], ["saul_618", 0, "end"], "period");
add("royal-david-hebron", "David rules Judah from Hebron", ["2SA.2.4", "2SA.2.11", "2SA.5.4", "2SA.5.5"], "David is thirty at accession and rules at Hebron seven years and six months. The year-level labels round the transition to c. 1003 BC within the existing c. 1010–970 BC reign; they do not turn seven-and-a-half years into an exact seven.", ["david_593", 30], ["david_593", 37], "period");
add("royal-david-jerusalem", "David rules all Israel from Jerusalem", ["2SA.5.3", "2SA.5.5", "1KI.2.11"], "The KJV gives thirty-three years at Jerusalem after seven years and six months at Hebron. Approximate annual endpoints preserve the shared forty-year summary and its rounding allowance.", ["royal-david-hebron", 0, "end"], ["david_593", 0, "end"], "period");
add("royal-solomon", "Solomon · reign", ["1KI.1.39", "1KI.11.42"], "The existing c. 970–930 BC working reign supplies context, not Solomon's birth or total lifespan. His accession is during David's final days; no long coregency is inferred.", ["solomon_677"], ["solomon_677", 0, "end"], "period");
add("royal-rehoboam", "Rehoboam of Judah · reign", ["1KI.14.21"], "Reuses the shared seventeen-year reign after the division. Jeroboam is the northern king, a different man and dynasty.", ["rehoboam_847"], ["rehoboam_847", 0, "end"], "period");
add("royal-ahab", "Ahab of Israel · reign", ["1KI.16.29", "1KI.22.37"], "Working c. 874–853 BC calendar context. The KJV's twenty-two regnal years allow inclusive/accession reckoning; the difference between the rounded endpoint numbers is not a replacement for that total.", -873, -852, "period", ["omri", "jehu"]);
add("royal-joram-israel", "Jehoram / Joram son of Ahab · Israel", ["2KI.3.1", "2KI.9.24"], "Working c. 852–841 BC reign; the KJV gives twelve years with regnal-year counting. This is Ahab's son ruling Israel, not Jehoram son of Jehoshaphat ruling Judah.", -851, -840, "period", ["jehu"]);
add("royal-hezekiah", "Hezekiah of Judah · reign", ["2KI.18.1", "2KI.18.2", "2KI.18.13"], "Reuses the shared sole-reign proposal. The Hoshea/Samaria synchronisms require consideration of a shared reign; this bar is not a resolution of every accession-year question.", ["hezekiah_944"], ["hezekiah_944", 0, "end"], "period");
add("royal-josiah", "Josiah of Judah · reign", ["2KI.22.1", "2KI.23.29"], "Reuses the shared c. 640–609 BC, thirty-one-year reign. The age of eight is his accession age, not the length of the reign.", ["josiah_849"], ["josiah_849", 0, "end"], "period");

unknown("samuel-birth", "Hannah's prayer and Samuel's birth", ["1SA.1.10", "1SA.1.20", "1SA.1.24"], "Birth, weaning, and dedication are successive episodes. Samuel's birth year and weaning age are unstated; no assumed age is used to place them on the calendar.");
unknown("samuel-shiloh", "Samuel serves at Shiloh; Eli's house warned", ["1SA.2.11", "1SA.2.18", "1SA.2.27", "1SA.3.4", "1SA.3.20"], "The childhood service, warnings, and calling precede the ark's capture. Neither Samuel's age at the call nor Eli's accession year is supplied.");
unknown("ark-captured", "The ark captured and Eli dies", ["1SA.4.11", "1SA.4.15", "1SA.4.18"], "Eli dies at ninety-eight after judging forty years. These numbers do not independently establish a BC year; his judgeship is not added after Samson as though regional periods cannot overlap.");
unknown("ark-philistines", "The ark among the Philistines and its return", ["1SA.5.1", "1SA.6.1", "1SA.6.13", "1SA.7.1"], "Seven months in Philistine territory precede the return. The absolute date is unknown. The twenty years later mentioned at Kirjath-jearim do not imply the ark immediately moved to David's Jerusalem after twenty years.");
unknown("samuel-mizpeh", "Israel returns to the LORD at Mizpeh", ["1SA.7.2", "1SA.7.5", "1SA.7.12", "1SA.7.15"], "The twenty-year notice leads into lamentation and the Mizpeh narrative. The closing account summarizes Samuel's judging; it is not all one day or a complete lifespan.");
unknown("request-king", "Israel asks Samuel for a king", ["1SA.8.1", "1SA.8.5", "1SA.8.22"], "Samuel is old, but his age and the interval before Saul's accession are not stated. The speech's future warnings are not all events occurring at this request.");
add("saul-anointed", "Saul anointed and publicly chosen", ["1SA.9.15", "1SA.10.1", "1SA.10.24"], "Placed near the beginning of the shared working reign. The private anointing and public selection are successive occasions; the BC label does not specify an exact day or Saul's age.", ["saul_618"]);
add("saul-jabesh", "Saul delivers Jabesh; the kingdom renewed", ["1SA.11.1", "1SA.11.11", "1SA.11.15", "1SA.12.1"], "The deliverance and renewal at Gilgal belong to Saul's opening kingship narrative. Samuel's following address recounts earlier deliverances without redating them to this occasion.", ["saul_618"]);
unknown("saul-michmash", "Saul and Jonathan against the Philistines", ["1SA.13.1", "1SA.13.8", "1SA.14.6", "1SA.14.24", "1SA.14.47"], "The KJV retains one year and two years in 1 Samuel 13:1. The seven-day wait and Jonathan's action belong to the opening reign narrative; chapter 14 also surveys later wars and family. No calendar date is imposed on that entire collection.");
unknown("saul-amalek", "The Amalek campaign and Saul rejected", ["1SA.15.3", "1SA.15.9", "1SA.15.23"], "This precedes David's anointing in the narrative, but no regnal year is supplied. The earlier Amalek history is recalled, not contemporary with this campaign.");
unknown("david-anointed", "David anointed and brought to Saul's court", ["1SA.16.13", "1SA.16.21"], "David's age is unstated. The anointing and service at court are distinguished from his later accession at thirty; no teenage age is invented.");
unknown("david-goliath", "David and Goliath", ["1SA.17.12", "1SA.17.33", "1SA.17.49"], "The text calls David a youth but does not give an age or regnal year. The battle is not assigned David's accession year or a guessed birth-to-battle interval.");
unknown("david-court", "David, Jonathan, and Saul's growing hostility", ["1SA.18.1", "1SA.18.9", "1SA.18.27", "1SA.19.10", "1SA.20.42"], "Friendship, marriage, attempted killings, and departure are successive episodes during Saul's reign. Their individual years are unstated.");
unknown("david-fugitive", "David flees; Saul attacks the priests of Nob", ["1SA.21.1", "1SA.21.10", "1SA.22.1", "1SA.22.18"], "Nob, the first visit to Gath, Adullam, and the attack on the priests belong to the fugitive narrative. This Gath visit is not merged with the later sixteen-month Philistine stay.");
unknown("david-keilah", "Keilah, the wilderness, and Saul spared in the cave", ["1SA.23.5", "1SA.23.14", "1SA.24.3", "1SA.24.7"], "The Keilah rescue and successive pursuits have no specified year. Sparing Saul in the cave is retained separately from the later camp incident.");
unknown("samuel-death-nabal", "Samuel dies; David encounters Nabal and Abigail", ["1SA.25.1", "1SA.25.32", "1SA.25.38", "1SA.25.42"], "Samuel's death precedes these later fugitive episodes, without a stated age or year. The ten days before Nabal's death are days, not a timeline interval measured in years.");
unknown("david-spares-camp", "David spares Saul in the camp", ["1SA.26.7", "1SA.26.11", "1SA.26.25"], "This second sparing episode is a night visit to the camp, distinct from the cave in chapter 24. No exact interval between them is given.");
add("david-ziklag", "David with Achish at Ziklag", ["1SA.27.6", "1SA.27.7", "1SA.29.11", "1SA.30.1"], "The KJV gives a full year and four months in Philistine territory. The two-year envelope allows annual rounding before Saul's death; it is a possible placement of that stay, not a replacement two-year duration. David is dismissed from the campaign before recovering Ziklag.", ["saul_618", -2, "end"], ["saul_618", 0, "end"], "date-window");
add("saul-final", "Saul's final campaign and death at Gilboa", ["1SA.28.4", "1SA.28.7", "1SA.31.4", "1SA.31.6"], "The Endor visit precedes the final battle. Uses the endpoint of the existing Saul reign, not a BC date supplied in the chapter or a conclusion about the age of Saul.", ["saul_618", 0, "end"]);
add("david-lament", "David hears of Saul's death and laments", ["2SA.1.1", "2SA.1.2", "2SA.1.17"], "The report follows the Gilboa battle and David's return from the Amalekites. The messenger's account is retained as his claim rather than silently replacing the death narrative in 1 Samuel 31.", ["saul_618", 0, "end"]);
unknown("ishbosheth", "Ish-bosheth and the struggle with David's house", ["2SA.2.10", "2SA.2.11", "2SA.3.1", "2SA.3.27", "2SA.4.7"], "Ish-bosheth is forty at accession and reigns two years; David rules Hebron seven years and six months. The two years are not expanded to cover all of David's Hebron period, and their exact start within it remains unassigned.");
add("david-jerusalem", "David made king over all Israel; Jerusalem taken", ["2SA.5.3", "2SA.5.5", "2SA.5.7"], "The shared year-level transition after Hebron is c. 1003 BC. The children and later Philistine battles also mentioned in this chapter are not all dated to the capture.", ["royal-david-jerusalem"]);
unknown("david-ark", "David brings the ark to Jerusalem", ["2SA.6.3", "2SA.6.7", "2SA.6.11", "2SA.6.12"], "The first attempt and Uzzah's death precede three months in Obed-edom's house and the later procession. The year within David's Jerusalem reign is not stated.");
unknown("david-covenant", "The promise concerning David's house", ["2SA.7.1", "2SA.7.12", "2SA.7.16"], "The promise is delivered after David has a house and rest from surrounding enemies. Its exact relation to the campaign summaries is not settled by chapter order; future descendants and fulfillment are not dated to the speech.");
unknown("david-campaigns", "David's campaigns and administration", ["2SA.8.1", "2SA.8.6", "2SA.8.15", "2SA.10.6", "2SA.10.19"], "Campaign and official lists summarize activity during David's reign. The Ammonite and Syrian war is narrated more fully in chapter 10; the summaries do not establish exact years for every victory.");
unknown("david-mephibosheth", "David receives Jonathan's son Mephibosheth", ["2SA.4.4", "2SA.9.6", "2SA.9.13"], "Mephibosheth was five when Saul and Jonathan died; his age on coming to David's table is unstated. He is Jonathan's son, distinct from Saul's son of the same name in 2 Samuel 21:8.");
unknown("david-bathsheba", "David, Bathsheba, and Uriah", ["2SA.11.1", "2SA.11.4", "2SA.11.17", "2SA.12.7", "2SA.12.18"], "The campaign season, wrongdoing, rebuke, and child's death form successive episodes. The child dies on the seventh day of the illness narrative; no birth year or exact BC date is supplied.");
unknown("solomon-birth-rabbah", "Solomon born; Rabbah taken", ["2SA.12.24", "2SA.12.26", "2SA.12.29"], "Solomon's birth and the conclusion of the Rabbah campaign are narrated here without an exact year. His later forty-year reign is not an age at accession and cannot supply his birth date.");
unknown("amnon-absalom", "Amnon, Tamar, and Absalom's revenge", ["2SA.13.14", "2SA.13.23", "2SA.13.29", "2SA.13.38"], "Two full years precede Absalom's revenge, followed by three years in Geshur. These explicit intervals are retained without inventing the initial calendar year.");
unknown("absalom-return", "Absalom returns and is reconciled to David", ["2SA.14.21", "2SA.14.28", "2SA.14.33"], "After the three years in Geshur, Absalom spends two full years in Jerusalem before seeing the king. The relative sequence is known but its absolute start is not.");
unknown("absalom-revolt", "Absalom's revolt and David's flight", ["2SA.15.7", "2SA.15.14", "2SA.16.5", "2SA.17.14", "2SA.18.15"], "The KJV says after forty years in 2 Samuel 15:7. Its starting point remains unresolved; it is not silently changed to four years or added as forty more years after Absalom's return. Flight, counsel, and the battle are successive episodes without a forced BC placement.");
unknown("david-restored", "David returns; Sheba's rebellion", ["2SA.19.15", "2SA.19.24", "2SA.20.1", "2SA.20.22"], "The return follows Absalom's defeat, with Sheba's revolt afterward. No absolute year is supplied, and the closing official list is not a lifespan list.");
unknown("david-famine", "The three-year famine and the Gibeonites", ["2SA.21.1", "2SA.21.7", "2SA.21.8", "2SA.21.14"], "A three-year famine occurs in the days of David. The closing collection need not follow Sheba chronologically. The KJV's Michal wording and the two distinct men named Mephibosheth are retained without silently substituting a different name.");
unknown("david-warriors", "Philistine battles and David's mighty men", ["2SA.21.15", "2SA.21.19", "2SA.23.8", "2SA.23.39"], "These lists recall several battles and people across David's reign. They are not all final-year events; the Goliath wording in 2 Samuel 21:19 is not used to redate David's encounter in 1 Samuel 17.");
unknown("david-song", "David's song of deliverance", ["2SA.22.1", "PSA.18.1"], "The introduction recalls deliverance from enemies and Saul. It does not specify a composition year or place all the recounted deliverances after the previous chapter.");
unknown("david-last-words", "David's last words", ["2SA.23.1", "2SA.23.5"], "The text identifies these as David's last words without assigning an exact date. The subsequent warrior list surveys earlier activity.");
unknown("david-census", "David's census, plague, and altar", ["2SA.24.8", "2SA.24.13", "2SA.24.18", "2SA.24.25"], "The census takes nine months and twenty days. Its position at the book's end does not establish David's last year. The offered seven-year famine in this KJV account is not replaced by a parallel account's number.");

add("solomon-accession", "Solomon anointed; David's final charge and death", ["1KI.1.39", "1KI.2.1", "1KI.2.10", "1KI.2.11"], "Placed at the shared c. 970 BC transition. David's charge recalls earlier actions by Joab and Shimei; their later executions are separate from those original incidents.", ["solomon_677"]);
unknown("solomon-established", "Solomon establishes his rule", ["1KI.2.25", "1KI.2.34", "1KI.2.39", "1KI.2.46"], "The succession judgments span time: Shimei leaves Jerusalem after three years. They are not all compressed into Solomon's accession day.");
add("solomon-wisdom", "Solomon at Gibeon and the judgment between two women", ["1KI.3.4", "1KI.3.5", "1KI.3.16", "1KI.5.5"], "The early-reign narrative precedes temple construction. This possible-year window is a bound, not the duration of the dream or judgment. No age is inferred from Solomon calling himself a little child.", ["solomon_677"], ["temple"], "date-window");
unknown("solomon-administration", "Solomon's officers, provision, and wisdom", ["1KI.4.1", "1KI.4.7", "1KI.4.29"], "The chapter surveys the kingdom's administration and wisdom without dating each appointment, proverb, or song. Its scope is broader than one year.");
add("solomon-preparations", "Solomon and Hiram prepare to build", ["1KI.5.1", "1KI.5.5", "1KI.5.13", "1KI.6.1"], "Preparations lead to the fourth-year foundation. The possible window extends from accession to that foundation; it is not four years measured for every timber delivery.", ["solomon_677"], ["temple"], "date-window");
add("solomon-palace", "Solomon's thirteen-year palace project", ["1KI.7.1", "1KI.9.10"], "The KJV states thirteen years for his own house and twenty years for the two houses. An absolute start for the palace and the relation of every furnishing project to it are not assigned merely from chapter order.", undefined, undefined, "period");
unknown("solomon-furnishings", "The temple's pillars, sea, and vessels", ["1KI.7.13", "1KI.7.23", "1KI.7.51"], "These furnishings belong to the temple work. The chapter's opening thirteen-year palace notice does not date all the temple vessels thirteen years after completion.");
unknown("temple-dedication", "The ark brought in; Solomon dedicates the temple", ["1KI.8.2", "1KI.8.6", "1KI.8.63", "1KI.6.38"], "The dedication assembly is in the seventh month; the completion notice gives the eleventh year's eighth month. The precise year linking these notices is not supplied here, so the dedication is not automatically placed before completion in the same year.");
add("solomon-two-houses", "The two-house building programme completed", ["1KI.6.1", "1KI.6.38", "1KI.7.1", "1KI.9.10"], "Working inference: count the stated twenty-year programme from the fourth-year foundation. This projects its close around 946 BC with annual rounding. It does not independently date every city, voyage, or transaction collected in chapter 9.", ["temple", 20]);
unknown("solomon-trade", "Solomon's cities, fleet, and the queen of Sheba", ["1KI.9.15", "1KI.9.26", "1KI.10.1", "1KI.10.22"], "Trade, building, the visit, and recurring voyages are collected without individual years. Ships arriving once in three years do not supply a single three-year visit by the queen.");
unknown("solomon-decline", "Solomon's later unfaithfulness and adversaries", ["1KI.11.4", "1KI.11.14", "1KI.11.23", "1KI.11.29"], "The account includes earlier histories of Hadad and Rezon alongside Solomon's later years and the word to Jeroboam. They are not all simultaneous with Solomon's death.");
add("solomon-death", "Solomon dies; Rehoboam succeeds", ["1KI.11.42", "1KI.11.43"], "The shared forty-year reign closes at the conventional c. 930 BC transition. The division follows the succession narrative.", ["solomon_677", 0, "end"]);
unknown("jeroboam-altars", "Jeroboam's altars and the man of God's warning", ["1KI.12.28", "1KI.13.1", "1KI.13.2", "1KI.13.24"], "The altar episode follows the division without an exact year. The naming of Josiah is a prophecy here, not an event in Josiah's much later reign; its fulfillment is mapped separately in 2 Kings 23.");
unknown("jeroboam-house", "Ahijah's word to Jeroboam's house", ["1KI.14.1", "1KI.14.6", "1KI.14.17", "1KI.14.20"], "The child's illness and death are not dated to Jeroboam's closing twenty-two-year reign notice. This Abijah, son of Jeroboam, is distinct from Judah's Abijam.");
add("shishak-judah", "Shishak comes against Jerusalem", ["1KI.14.25", "1KI.14.26"], "Fifth year of Rehoboam. The possible-year window counts from the shared accession with allowance for accession and inclusive-year reckoning; it does not date all of Rehoboam's reign to this invasion.", ["rehoboam_847", 4], ["rehoboam_847", 5], "date-window");
unknown("early-divided-kings", "Abijam, Asa, Nadab, and Baasha", ["1KI.15.1", "1KI.15.2", "1KI.15.10", "1KI.15.25", "1KI.15.28", "1KI.15.33", "1KI.16.8"], "Judah's Abijam reigns three years and Asa forty-one; Israel's Nadab two and Baasha twenty-four. Cross-kingdom synchronisms are retained, without stacking these overlapping reigns into a single succession or deriving lifespans from them. Nadab spans Asa year 2 to 3 and Baasha 3 to 26; those year labels do not equal elapsed anniversaries. See Divided-kingdom year counting in Sources & method.", ["regnalCounting"]);
unknown("omri-succession", "Elah, Zimri, Tibni, and Omri", ["1KI.16.8", "1KI.16.15", "1KI.16.16", "1KI.16.21", "1KI.16.23", "1KI.16.24", "1KI.16.29"], "Elah's two years, Zimri's seven days, the Omri/Tibni division, and Omri's twelve years are distinct. The divided and sole-rule notices require separate reckoning; the text does not make Zimri's seven days seven years. Omri is made king in Asa year 27; the year-31 beginning and Ahab's year-38 succession require a distinction between reckonings. Counting 27 through 38 inclusively yields twelve labels, but does not independently date Tibni's death. See Divided-kingdom year counting in Sources & method.", ["regnalCounting"]);
add("elijah-drought", "Elijah's drought, Carmel, and the return of rain", ["1KI.17.1", "1KI.18.1", "1KI.18.38", "1KI.18.45", "LUK.4.25", "JAS.5.17"], "The possible-date envelope is Ahab's reign, not a twenty-one-year drought. The KJV's three years and six months in Luke and James are retained alongside the third-year message in 1 Kings 18; the notices' starting points are not silently equated.", ["royal-ahab"], ["royal-ahab", 0, "end"], "date-window");
add("elijah-horeb", "Elijah at Horeb; Elisha called", ["1KI.19.8", "1KI.19.15", "1KI.19.19"], "After Carmel in the narrative, within Ahab's reign. Forty days and nights of travel are retained in the evidence. The commissions concerning Hazael and Jehu anticipate later events, not immediate simultaneous accessions.", ["royal-ahab"], ["royal-ahab", 0, "end"], "date-window");
add("ahab-syria", "Ahab's wars with Ben-hadad", ["1KI.20.1", "1KI.20.22", "1KI.20.26", "1KI.20.34"], "Two campaigning seasons are narrated, the second at the return of the year. Their exact years within Ahab's reign are not supplied; this window is not the duration of a battle.", ["royal-ahab"], ["royal-ahab", 0, "end"], "date-window");
add("naboth", "Naboth's vineyard and Elijah's judgment", ["1KI.21.1", "1KI.21.13", "1KI.21.19", "1KI.21.29"], "Located within Ahab's reign without an exact year. The judgment postponed to his son's days is distinguished from the date of the warning.", ["royal-ahab"], ["royal-ahab", 0, "end"], "date-window");
add("ahab-death", "Ahab dies at Ramoth-gilead", ["1KI.22.1", "1KI.22.2", "1KI.22.34", "1KI.22.37"], "Uses the conventional c. 853 BC endpoint of Ahab's reign. The three-year no-war notice precedes this campaign. The Assyrian Qarqar battle is a different campaign and is not substituted for Ramoth-gilead.", ["royal-ahab", 0, "end"]);
unknown("jehoshaphat-summary", "Jehoshaphat of Judah and Ahaziah of Israel", ["1KI.22.42", "1KI.22.48", "1KI.22.51"], "The chapter closes with Jehoshaphat's twenty-five-year reign and fleet loss, then Ahaziah son of Ahab's two-year reign in Israel. Their years are not all Ahab's death year; this Ahaziah is distinct from Ahaziah of Judah.");
add("ahaziah-israel-death", "Ahaziah son of Ahab dies; Jehoram succeeds in Israel", ["2KI.1.2", "2KI.1.16", "2KI.1.17", "1KI.22.51"], "Working c. 852 BC transition after the two regnal years counted for Ahaziah. Jehoram son of Ahab succeeds because Ahaziah has no son; Judah's Jehoram is another king.", ["royal-joram-israel"]);
unknown("elijah-taken", "Elijah taken up; Elisha begins his ministry", ["2KI.2.1", "2KI.2.11", "2KI.2.15"], "The succession narrative lies near the Ahaziah/Jehoram transition, but no exact year is stated. Being taken up is not described as a death with a known lifespan.");
add("moab-campaign", "Israel, Judah, and Edom campaign against Moab", ["2KI.3.1", "2KI.3.4", "2KI.3.7", "2KI.3.27"], "Jehoram son of Ahab is Israel's king; Jehoshaphat leads Judah. The broad Israelite reign gives a possible outer window, not proof of Jehoshaphat's participation throughout it. Moab's earlier rebellion follows Ahab's death.", ["royal-joram-israel"], ["royal-joram-israel", 0, "end"], "date-window");
unknown("elisha-households", "Elisha: oil, the Shunammite, food, and provision", ["2KI.4.1", "2KI.4.8", "2KI.4.16", "2KI.4.18", "2KI.4.38", "2KI.4.42"], "This collection spans different households, a promised birth, a child's growth, and a famine. The events are not forced into one year; no exact age is assigned to the Shunammite's child.");
unknown("naaman", "Naaman healed; Gehazi judged", ["2KI.5.1", "2KI.5.7", "2KI.5.14", "2KI.5.27"], "Neither the king of Israel nor the king of Syria is named in this episode. Their identities and the exact year are not assumed solely from surrounding chapters.");
unknown("elisha-dothan", "The axe head and the deliverance at Dothan", ["2KI.6.5", "2KI.6.13", "2KI.6.18", "2KI.6.23"], "Distinct incidents involving the sons of the prophets and the Syrian raiders. The later siege is a separate episode; these are not all dated by chapter order.");
unknown("samaria-siege-elisha", "Samaria besieged and unexpectedly relieved", ["2KI.6.24", "2KI.6.25", "2KI.7.1", "2KI.7.6", "2KI.7.16"], "Ben-hadad is named, but the Israelite king is not. The next-day fulfillment is explicit; the BC year and siege length are not. This is not the later Assyrian siege ending in 722 BC.");
add("shunammite-famine", "The Shunammite's seven-year sojourn and return", ["2KI.8.1", "2KI.8.2", "2KI.8.3", "2KI.8.4"], "The KJV gives seven years away during famine, followed by a property appeal while Gehazi recounts the child's restoration. The passage recalls earlier events; its relation to Gehazi's leprosy and other famines is not settled by assuming strict chapter order.", undefined, undefined, "period");
unknown("hazael", "Elisha meets Hazael; Ben-hadad dies", ["2KI.8.7", "2KI.8.12", "2KI.8.15"], "The encounter, prediction, and accession precede Hazael's later campaigns. No exact year is assigned here from an uncertain identification of every king called Ben-hadad.");
unknown("judah-jehoram-ahaziah", "Jehoram son of Jehoshaphat and Ahaziah · Judah", ["2KI.8.16", "2KI.8.17", "2KI.8.25", "2KI.8.26"], "Judah's Jehoram has eight regnal years, with Jehoshaphat still named at accession; his son Ahaziah reigns one year. These men are distinct from the northern Jehoram and Ahaziah, sons of Ahab. The KJV gives Ahaziah twenty-two at accession here; a discrepant parallel is not silently substituted.");
add("jehu-coup", "Jehu's coup; Joram, Ahaziah, and Jezebel killed", ["2KI.9.6", "2KI.9.24", "2KI.9.27", "2KI.9.33", "2KI.10.1"], "Working c. 841 BC transition. The Assyrian evidence places tribute from Jehu around this time, supporting the calendar framework without narrating the coup itself. Joram of Israel and Ahaziah of Judah are distinct victims.", -840, undefined, "event", ["jehu", "assyrianIsrael"]);
add("royal-jehu", "Jehu of Israel · reign", ["2KI.10.28", "2KI.10.32", "2KI.10.36"], "Twenty-eight regnal years in the KJV. The working 841 BC accession and inclusive-year allowance give approximately 841–814 BC; the removal of Baal worship and later territorial losses are not all accession-day events.", ["jehu-coup"], -813, "period", ["jehu"]);
add("athaliah", "Athaliah rules while Joash is hidden", ["2KI.11.1", "2KI.11.3", "2KI.11.4"], "Six years of hiding lead to the seventh-year intervention. Counting approximately from the 841 BC transition gives c. 841–835 BC; month and accession boundaries remain approximate.", ["jehu-coup"], ["jehu-coup", 6], "period");
add("joash-judah-crowned", "Joash son of Ahaziah crowned in Judah", ["2KI.11.12", "2KI.11.21", "2KI.12.1"], "Joash is seven at accession, in Jehu's seventh year. The working c. 835 BC placement follows the six years hidden under Athaliah. He is not Jehoash son of Jehoahaz, later king of Israel.", ["athaliah", 0, "end"]);
add("joash-repairs", "Joash of Judah reorganizes temple repairs", ["2KI.12.6", "2KI.12.9", "2KI.12.11"], "In Joash's twenty-third year the earlier repair arrangements have not succeeded. The window allows ordinal/accession counting from the working accession; it dates the intervention, not a twenty-three-year repair project or the final completion day.", ["joash-judah-crowned", 22], ["joash-judah-crowned", 23], "date-window");
unknown("joash-judah-end", "Joash of Judah: Hazael's threat and the final conspiracy", ["2KI.12.1", "2KI.12.17", "2KI.12.20"], "The chapter spans a forty-year reign. Hazael's threat and the assassination follow the repairs in the account, but are not both assigned the twenty-third year.");
unknown("northern-joash", "Jehoahaz and Jehoash / Joash · Israel", ["2KI.13.1", "2KI.13.10", "2KI.13.25"], "Jehoahaz son of Jehu reigns seventeen years; Jehoash his son sixteen. These northern kings are distinct from Jehoahaz son of Josiah and from Joash son of Ahaziah in Judah. No simple end-to-end arithmetic overrides their synchronisms with Judah.");
unknown("elisha-death", "Elisha's final prophecy, death, and a later revival", ["2KI.13.14", "2KI.13.19", "2KI.13.20", "2KI.13.21"], "Elisha's death is under Jehoash of Israel, but no age or exact year is supplied. The man revived at his grave is a later incident, not Elisha's own resurrection or an event dated to his death day.");
unknown("amaziah-jeroboam", "Amaziah of Judah and Jeroboam II of Israel", ["2KI.14.2", "2KI.14.13", "2KI.14.17", "2KI.14.23", "2KI.14.25"], "Amaziah's twenty-nine years and Jeroboam II's forty-one belong to different kingdoms. Amaziah outlives northern Joash fifteen years. Jonah's word is recalled, but no year for his Nineveh mission follows from the territorial-restoration notice.");
unknown("late-northern-kings", "Azariah, Jotham, and Israel's changing kings", ["2KI.15.2", "2KI.15.8", "2KI.15.13", "2KI.15.17", "2KI.15.23", "2KI.15.27", "2KI.15.30", "2KI.15.33"], "The survey spans Azariah/Uzziah's fifty-two years, Jotham's sixteen, and Israel's six-month, one-month, ten-year, two-year, and twenty-year reign notices. Pekah and the twentieth-year Jotham reference require further synchronism work; the totals are not changed to force a simple sequence.");
add("tiglath-north", "Tiglath-pileser takes northern Israel's towns", ["2KI.15.29", "2KI.15.30"], "Working c. 732 BC intervention from Assyrian campaign chronology. This is separate from Samaria's later fall and does not date every accession in the chapter.", -731, undefined, "event", ["tiglath", "assyrianIsrael"]);
add("ahaz-damascus", "Ahaz appeals to Assyria; Damascus falls", ["2KI.16.5", "2KI.16.7", "2KI.16.9", "2KI.16.10"], "The campaign setting uses the conventional c. 732 BC fall of Damascus. Ahaz's appeal precedes it and his visit follows; not every change to temple worship in the chapter is asserted to occur on that same date.", -731, undefined, "event", ["tiglath"]);
unknown("ahaz-reign", "Ahaz of Judah: reign and temple changes", ["2KI.16.2", "2KI.16.11", "2KI.16.17"], "Sixteen regnal years are given for Ahaz. The book's synchronisms with Pekah, Jotham, and Hezekiah require shared-reign/calendar analysis; the Damascus anchor alone does not settle all endpoints.");
unknown("samaria-resettled", "The northern kingdom's sins and later resettlement", ["2KI.17.7", "2KI.17.24", "2KI.17.41"], "The explanation looks back over Israel's history, then describes resettlement and continuing worship practices after the conquest. These are not all events in the single year of Samaria's fall.");
add("hezekiah-recovery", "Hezekiah's illness and promised fifteen years", ["2KI.20.1", "2KI.20.6", "2KI.18.13"], "Subtracting the promised fifteen years from the shared reign endpoint places recovery around 701 BC. This is a working inference; the promised defense against Assyria means the chapter's position after Sennacherib's death notice cannot be read as a strict later sequence.", ["hezekiah_944", -15, "end"]);
unknown("hezekiah-envoys", "The Babylonian envoys visit Hezekiah", ["2KI.20.12", "2KI.20.13", "2KI.20.17"], "The letter and visit follow news of the illness, without a separately supplied year. The future Babylonian removal of treasures is a warning here, not the current event or an accession date for the named Babylonian ruler.");
unknown("manasseh-amon", "Manasseh and Amon rule Judah", ["2KI.21.1", "2KI.21.19", "2KI.21.23", "2KI.21.24"], "Manasseh reigns fifty-five years and Amon two. Simply placing all fifty-five after Hezekiah's sole reign conflicts with the existing calendar anchors; potential coregency must be evaluated. The numbers remain intact and no fabricated absolute endpoints are supplied.");
add("josiah-law", "Josiah's eighteenth year: law found and covenant renewed", ["2KI.22.3", "2KI.22.8", "2KI.23.3", "2KI.23.23"], "The eighteenth-year notices connect the repairs, book discovery, covenant, and Passover. The c. 623–622 BC window allows accession/inclusive counting from the shared reign; it is not a two-year duration for one ceremony.", ["josiah_849", 17], ["josiah_849", 18], "date-window");
add("josiah-bethel", "Josiah removes the altar at Bethel", ["2KI.23.15", "2KI.23.16", "2KI.23.17", "1KI.13.2"], "The reform narrative recalls the earlier man of God's warning. This working eighteenth-year setting dates Josiah's action, not the centuries-earlier prophecy itself.", ["josiah-law"], ["josiah-law", 0, "end"], "date-window");
add("josiah-death", "Josiah dies at Megiddo", ["2KI.23.29", "2KI.23.30"], "Uses the shared c. 609 BC endpoint. The later transition to Jehoahaz and then Jehoiakim is distinguished from Josiah's earlier reform.", ["josiah_849", 0, "end"]);
add("jehoahaz-jehoiakim", "Jehoahaz removed; Jehoiakim installed in Judah", ["2KI.23.31", "2KI.23.33", "2KI.23.34", "2KI.23.36"], "Jehoahaz son of Josiah reigns three months before Pharaoh-nechoh installs Eliakim, renamed Jehoiakim. Placed at the c. 609 BC succession, not as the entire duration of Jehoiakim's eleven regnal years.", ["josiah-death"]);
unknown("jehoiakim-babylon", "Jehoiakim serves Babylon and rebels", ["2KI.24.1", "2KI.24.2", "2KI.24.6"], "Three years of service precede rebellion; the chapter does not independently identify their starting year. The later 597 BC capture under Jehoiachin does not date the whole Jehoiakim episode.");
add("zedekiah-appointed", "Mattaniah renamed Zedekiah and installed", ["2KI.24.17", "2KI.24.18"], "After Jehoiachin's deportation, the king of Babylon installs his uncle Mattaniah and renames him Zedekiah. The c. 597 BC anchor dates this appointment, not the destruction eleven regnal years later.", ["jerusalem-597"]);
add("jerusalem-final-siege", "The final siege of Jerusalem", ["2KI.25.1", "2KI.25.2", "2KI.25.3", "JER.39.1", "JER.39.2"], "The siege begins in Zedekiah's ninth year, tenth month and reaches the breach in his eleventh year, fourth month. The rounded span uses the shared 586 BC destruction model; a 587 BC model shifts it earlier. Two calendar-year labels do not mean exactly two elapsed years, and interruptions are not ruled out.", ["temple-destroyed", -2], ["temple-destroyed"], "period");
unknown("gedaliah", "Gedaliah appointed, killed, and the flight to Egypt", ["2KI.25.22", "2KI.25.25", "2KI.25.26"], "The assassination is in a seventh month after the destruction narrative, but its year is not explicitly numbered here. It is not automatically the destruction year or Jehoiachin's much later release year.");

export function buildKingsContext(chronology: TimelineRecord[]): ContextTimelineRecord[] {
  return buildAnchoredContext(episodes, chronology);
}

// Two historical entries add contemporary context without making their evidence
// an account of every biblical episode in those rulers' time.
export const KINGS_HISTORICAL_RECORDS: ContextTimelineRecord[] = [
  { id: "jehu-tribute", label: "Jehu's tribute recorded by Assyria", era: "history", track: "historical", kind: "event", start: -840, startStatus: "approximate", references: ["2KI.9.2"], sources: ["assyrianIsrael", "jehu"], note: "The Assyrian record places tribute from Jehu around 841 BC. Its House of Omri designation concerns Israel's royal/political identity, not proof that Jehu was Omri's biological son; Kings identifies Jehu as son of Jehoshaphat son of Nimshi; this father is not identified as Judah's king. The tribute is not narrated in 2 Kings 9–10." },
  { id: "tiglath-reign", label: "Tiglath-pileser III · reign", era: "history", track: "historical", kind: "period", start: -743, end: -726, startStatus: "approximate", endStatus: "approximate", references: [], sources: ["tiglath"], note: "Displays c. 744–727 BC following the cited regnal convention; 745 BC is also used for accession. The c. 732 BC Damascus and Israel campaign falls within the reign. The entire reign is not the duration of that campaign." },
];

type Chapter = [topic: string, ids: string, verses: string, contextIds?: string, note?: string];
export const KINGS_CHAPTER_TIMELINE_MAP: Record<string, Record<number, ChapterMapping>> = {};
function chapters(book: string, code: string, rows: Chapter[]) {
  KINGS_CHAPTER_TIMELINE_MAP[book] = Object.fromEntries(rows.map(([topic, ids, verses, contextIds = "", note], index) => [index + 1, {
    ids: ids.split(" "), contextIds: contextIds ? contextIds.split(" ") : [],
    references: verses.split(" ").map(verse => `${code}.${index + 1}.${verse}`),
    note: `${topic}. ${note ?? "Selected episodes retain their own dates or uncertainty; a surrounding reign is context, not a date assigned to every verse."}`,
  }]));
}
